# The first white cube is held at the fingertips. I will release it over the pan interior and then approach the remaining near white cube from above.
def fast_pose(target, grip, n=6):
    global obs,terminated,truncated
    s=get_observation()['state']
    a={k:list(s[k]) for k in ['left_ee_pose','right_ee_pose','left_ee_joint_state','right_ee_joint_state']}
    a['right_ee_pose']=list(target)
    a['right_ee_joint_state']=[grip]
    for i in range(n):
        obs,reward,terminated,truncated,info=step(a)
        if terminated or truncated: break
    p=obs['state']['right_ee_pose']
    err=sum((float(p[j])-target[j])**2 for j in range(3))**0.5
    print('fast',n,'error',err,'pose',list(p))
    return err<0.006 and not(terminated or truncated)
